import pysat
from pysat import SATSolver
from pysat.formula import CNF

# Let's try to encode N-Queens for N=27
n = 27

# Variables: x_{i,j} = i*n + j + 1 (1-indexed)
def var(i, j):
    return i * n + j + 1

cnf = CNF()

# At least one queen per row
for i in range(n):
    clause = [var(i, j) for j in range(n)]
    cnf.append(clause)

# At most one queen per row (pairwise)
for i in range(n):
    for j1 in range(n):
        for j2 in range(j1+1, n):
            cnf.append([-var(i, j1), -var(i, j2)])

# At most one queen per column
for j in range(n):
    for i1 in range(n):
        for i2 in range(i1+1, n):
            cnf.append([-var(i1, j), -var(i2, j)])

# At most one queen per diagonal (both directions)
# Main diagonal: i-j constant
for d in range(-(n-1), n):
    for i1 in range(n):
        j1 = i1 - d
        if 0 <= j1 < n:
            for i2 in range(i1+1, n):
                j2 = i2 - d
                if 0 <= j2 < n:
                    cnf.append([-var(i1, j1), -var(i2, j2)])

# Anti-diagonal: i+j constant
for s in range(2*n - 1):
    for i1 in range(n):
        j1 = s - i1
        if 0 <= j1 < n:
            for i2 in range(i1+1, n):
                j2 = s - i2
                if 0 <= j2 < n:
                    cnf.append([-var(i1, j1), -var(i2, j2)])

# Fixed assignments
fixed = {9: 23, 12: 13, 18: 1, 21: 21, 26: 14}
for i, j in fixed.items():
    cnf.append([var(i, j)])

print(f"Number of clauses: {len(cnf.clauses)}")
print(f"Number of variables: {n*n}")

# Solve
solver = SATSolver()
solver.append_formula(cnf)
status = solver.solve()
print(f"Status: {status}")
if status:
    model = solver.get_model()
    # Extract solution
    solution = [0] * n
    for i in range(n):
        for j in range(n):
            v = var(i, j)
            if v in model:
                solution[i] = j
                break
    print("Solution:", solution)
    # Verify
    # Check fixed
    for i, j in fixed.items():
        assert solution[i] == j, f"Fixed mismatch at row {i}: expected {j}, got {solution[i]}"
    # Check attacks
    ok = True
    for i1 in range(n):
        for i2 in range(i1+1, n):
            if solution[i1] == solution[i2] or abs(solution[i1] - solution[i2]) == abs(i1 - i2):
                print(f"Conflict: ({i1},{solution[i1]}) and ({i2},{solution[i2]})")
                ok = False
    if ok:
        print("Valid solution!")
else:
    print("UNSAT")

